package com.schedora.repository; import com.schedora.model.Booking; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; public interface BookingRepository extends JpaRepository<Booking,Long>{ List<Booking> findByCustomerIdOrderByCreatedAtDesc(Long id); List<Booking> findByServiceOwnerIdOrderByCreatedAtDesc(Long id); boolean existsByServiceIdAndAppointmentDateAndAppointmentTimeAndStatusNot(Long serviceId,String date,String time,String status); List<Booking> findByServiceIdAndAppointmentDateAndStatusNot(Long serviceId,String date,String status); }
